 async (err: Error, context: PartitionContext) =\u003e {\r\n        console.error(\r\n          `  ✗ Error on partition ${context.partitionId}: ${err.message}`\r\n        );\r\n      },\r\n    },\r\n    { startPosition: earliestEventPosition }\r\n  );\r\n\r\n  // 7 – Graceful shutdown on SIGINT / SIGTERM\r\n  const shutdown = async (): Promise\u003cvoid\u003e =\u003e {\r\n    console.log(\"\\nShutting down…\");\r\n    await subscription.close();\r\n    await consumer.close();\r\n    console.log(\"Consumer closed. Goodbye!\");\r\n    process.exit(0);\r\n  };\r\n\r\n  process.on(\"SIGINT\", shutdown);\r\n  process.on(\"SIGTERM\", shutdown);\r\n\r\n  console.log(\"Listening for events (Ctrl+C to stop)…\");\r\n}\r\n\r\n// ---------------------------------------------------------------------------\r\n// Main\r\n// ---------------------------------------------------------------------------\r\nasync function main(): Promise\u003cvoid\u003e {\r\n  console.log(\"=== Azure Event Hubs Streaming Demo ===\\n\");\r\n\r\n  await sendEvents();\r\n\r\n  console.log();\r\n\r\n  await receiveEvents();\r\n}\r\n\r\nmain().catch((err) =\u003e {\r\n  console.error(\"Fatal error:\", err);\r\n  process.exit(1);\r\n});\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"dist\",\r\n    \"rootDir\": \"src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"declaration\": true\r\n  },\r\n  \"include\": [\"src/**/*\"]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.